+function buildWall() {
+  const BW = 0.5;
+  const BH = 0.24;
+  const BD = 0.2;
+  const cols = params.columns;
+  const rows = params.rows;
+  const depth = params.depth;
+  const bricks = [];
+  for (let layer = 0; layer < depth; layer++) {
+    const x = WALL_FRONT + BD * 0.5 + layer * BD;
+    for (let row = 0; row < rows; row++) {
+      const y = BH * 0.5 + row * BH;
+      const z0 = -cols * BW * 0.5;
+      if (row % 2 === 0) {
+        for (let c = 0; c < cols; c++) {
+          bricks.push({ x, y, z: z0 + BW * (c + 0.5), hx: BD * 0.5, hy: BH * 0.5, hz: BW * 0.5, mass: params.brickMass, half: false, id: bricks.length });
+        }
+      } else {
+        bricks.push({ x, y, z: z0 + BW * 0.25, hx: BD * 0.5, hy: BH * 0.5, hz: BW * 0.25, mass: params.brickMass * 0.5, half: true, id: bricks.length });
+        for (let c = 0; c < cols - 1; c++) {
+          bricks.push({ x, y, z: z0 + BW * (1 + c), hx: BD * 0.5, hy: BH * 0.5, hz: BW * 0.5, mass: params.brickMass, half: false, id: bricks.length });
+        }
+        bricks.push({ x, y, z: z0 + BW * (cols - 0.25), hx: BD * 0.5, hy: BH * 0.5, hz: BW * 0.25, mass: params.brickMass * 0.5, half: true, id: bricks.length });
+      }
+    }
+  }
+  const geo = new THREE.BoxGeometry(BD * 0.9, BH * 0.9, BW * 0.96);
+  brickMesh = new THREE.InstancedMesh(geo, brickMat, bricks.length);
+  brickMesh.castShadow = true;
+  brickMesh.receiveShadow = true;
+  brickMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(bricks.length * 3), 3);
+  brickMesh.frustumCulled = false;
+  dynamic.add(brickMesh);
+  const color = new THREE.Color();
+  const dummy = new THREE.Object3D();
+  brickBodies = [];
+  for (let i = 0; i < bricks.length; i++) {
+    const b = bricks[i];
+    const body = world.createRigidBody(
+      RAPIER.RigidBodyDesc.dynamic()
+        .setTranslation(b.x, b.y, b.z)
+        .setLinearDamping(0.045)
+        .setAngularDamping(0.12)
+        .setCcdEnabled(true)
+        .setCanSleep(true)
+    );
+    const col = world.createCollider(
+      RAPIER.ColliderDesc.cuboid(b.hx, b.hy, b.hz)
+        .setMass(b.mass)
+        .setFriction(params.brickFriction)
+        .setRestitution(params.brickRestitution)
+        .setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS)
+        .setContactForceEventThreshold(1800),
+      body
+    );
+    tagCollider(col, 'brick', body);
+    brickBodies.push(body);
+    const n = hash01(i * 97 + 13);
+    color.setHSL(0.012 + n * 0.03, 0.38 + n * 0.28, 0.22 + n * 0.16);
+    brickMesh.setColorAt(i, color);
+    dummy.position.set(b.x, b.y, b.z);
+    dummy.scale.set(1, 1, b.half ? 0.5 : 1);
+    dummy.rotation.set(0, 0, 0);
+    dummy.updateMatrix();
+    brickMesh.setMatrixAt(i, dummy.matrix);
+  }
+  brickMesh.instanceColor.needsUpdate = true;
+  brickMesh.instanceMatrix.needsUpdate = true;
+}
