+function buildStaticsPhysics() {
+  const ground = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(20, -0.6, 0));
+  const gcol = world.createCollider(
+    RAPIER.ColliderDesc.cuboid(80, 0.6, 50)
+      .setFriction(params.groundFriction)
+      .setRestitution(0.03),
+    ground
+  );
+  tagCollider(gcol, 'ground', ground);
+  groundBodies.add(ground.handle);
+
+  for (const side of [-1, 1]) {
+    const curb = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(TRACK_LEN / 2, 0.05, side * 5.15));
+    const cc = world.createCollider(
+      RAPIER.ColliderDesc.cuboid(TRACK_LEN / 2, 0.05, 0.18)
+        .setFriction(params.groundFriction)
+        .setRestitution(0.05),
+      curb
+    );
+    tagCollider(cc, 'ground', curb);
+    groundBodies.add(curb.handle);
+    const rail = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(TRACK_LEN / 2, 0.48, side * 7.15));
+    const rc = world.createCollider(
+      RAPIER.ColliderDesc.cuboid(TRACK_LEN / 2, 0.32, 0.08)
+        .setFriction(0.6)
+        .setRestitution(0.08),
+      rail
+    );
+    tagCollider(rc, 'static', rail);
+  }
+}
