+function clearDynamic() {
+  while (dynamic.children.length) dynamic.remove(dynamic.children[0]);
+  for (const g of geoCache.values()) g.dispose();
+  geoCache.clear();
+  if (brickMesh) {
+    brickMesh.geometry.dispose();
+    brickMesh = null;
+  }
+}
