document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xb9c8d6, 55, 150);

const camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.18, 320);
const lookTarget = new THREE.Vector3(20, 1, 0);
camera.position.set(1.2, 4.6, 14.5);

const pmrem = new THREE.PMREMGenerator(renderer);
const envTex = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environment = envTex;
scene.environmentIntensity = 0.52;
pmrem.dispose();
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.02;

const hemi = new THREE.HemisphereLight(0xc9daf0, 0x6d5b44, 0.38);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff4e4, 4.15);
sun.castShadow = true;
sun.shadow.mapSize.set(4096, 4096);
sun.shadow.bias = -0.00018;
sun.shadow.normalBias = 0.035;
sun.shadow.camera.near = 0.5;
sun.shadow.camera.far = 90;
scene.add(sun);
scene.add(sun.target);

const rt = new THREE.WebGLRenderTarget(
  Math.floor(window.innerWidth * renderer.getPixelRatio()),
  Math.floor(window.innerHeight * renderer.getPixelRatio()),
  { type: THREE.HalfFloatType, samples: 4 }
);
const composer = new EffectComposer(renderer, rt);
const renderPass = new RenderPass(scene, camera);
composer.addPass(renderPass);
const ssaoPass = new SSAOPass(scene, camera, window.innerWidth, window.innerHeight, 16);
ssaoPass.kernelRadius = 0.72;
ssaoPass.minDistance = 0.008;
ssaoPass.maxDistance = 0.42;
composer.addPass(ssaoPass);
const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.38, 0.48, 1.05
);
composer.addPass(bloomPass);
composer.addPass(new OutputPass());

const geoCache = new Map();

  impactTime = 0;
  settled = false;
  settledTime = 0;
  shake = 0;
  cruise = true;
  userYaw = 0;
  camReady = false;
  buildStaticsPhysics();
  buildWall();
  buildCar();
  placeCamera(0, true);
}

function bodyVec(body, out) {
  const t = body.translation();
  out.set(t.x, t.y, t.z);
  return out;
}
const _a = new THREE.Vector3();
const _b = new THREE.Vector3();
const _dummy = new THREE.Object3D();

function syncGraphics() {
  for (const rec of partsByHandle.values()) {
    const t = rec.body.translation();
    const r = rec.body.rotation();
    rec.obj.position.set(t.x, t.y, t.z);
    rec.obj.quaternion.set(r.x, r.y, r.z, r.w);
  }
  if (!brickMesh) return;
  for (let i = 0; i < brickBodies.length; i++) {
    const t = brickBodies[i].translation();
    const r = brickBodies[i].rotation();
    _dummy.position.set(t.x, t.y, t.z);
    _dummy.quaternion.set(r.x, r.y, r.z, r.w);
    _dummy.scale.set(1, 1, brickMesh.getMatrixAt(i, _dummy.matrix) && false ? 1 : 1);
    brickMesh.getMatrixAt(i, _m);
    const half = _m.elements[10] < 0.75;
    _dummy.scale.set(1, 1, half ? 0.5 : 1);
    _dummy.updateMatrix();
    brickMesh.setMatrixAt(i, _dummy.matrix);
  }
  brickMesh.instanceMatrix.needsUpdate = true;
}
const _m = new THREE.Matrix4();

function spawnParticle(x, y, z, vx, vy, vz, life, kind) {
  let idx = -1;
  for (let i = 0; i < MAXP; i++) {
    if (pLife[i] <= 0) { idx = i; break; }
  }
  if (idx < 0) return;
  pPos[idx * 3] = x;
  pPos[idx * 3 + 1] = y;
  pPos[idx * 3 + 2] = z;
  pVel[idx * 3] = vx;
  pVel[idx * 3 + 1] = vy;
  pVel[idx * 3 + 2] = vz;
  pLife[idx] = life;
  pKind[idx] = kind;
}
function burst(x, y, z, n, speed, life, kind) {
  for (let i = 0; i < n; i++) {
    const rx = vfxRng() - 0.5;
    const ry = vfxRng();
    const rz = vfxRng() - 0.5;
    spawnParticle(
      x + rx * 0.3, y + ry * 0.2, z + rz * 0.3,
      rx * speed, ry * speed * 0.8 + (kind ? 0.6 : 1.2), rz * speed,
      life * (0.65 + vfxRng() * 0.5), kind
    );
  }
}
function tickParticles() {
  for (let i = 0; i < MAXP; i++) {
    if (pLife[i] <= 0) continue;
    pVel[i * 3 + 1] -= params.gravity * DT * (pKind[i] > 0.5 ? 0.35 : 1);
    pPos[i * 3] += pVel[i * 3] * DT;
    pPos[i * 3 + 1] += pVel[i * 3 + 1] * DT;
    pPos[i * 3 + 2] += pVel[i * 3 + 2] * DT;

  const doorSpec = [
    ['FL', 0.4, 0.7, 0.81, 0.36, 0.2],
    ['FR', 0.4, 0.7, -0.81, 0.36, 0.2],
    ['RL', -0.48, 0.68, 0.81, 0.36, 0.18],
    ['RR', -0.48, 0.68, -0.81, 0.36, 0.18]
  ];
  for (const [id, x, y, z, hx, hy] of doorSpec) {
    const d = addPart('door' + id, x, y, z, hx, hy, 0.09, m(BASE_MASS.door), 0.5);
    mesh(d.obj, hx * 2, hy * 2, 0.18, 0, 0, 0, paint);
    mesh(d.obj, 0.12, 0.035, 0.03, hx * 0.15, -0.02, Math.sign(z) * 0.1, chrome);
    if (id[0] === 'F') {
      mesh(d.obj, 0.1, 0.08, 0.12, hx * 0.7, 0.16, Math.sign(z) * 0.12, plastic);
      mesh(d.obj, 0.08, 0.06, 0.1, hx * 0.85, 0.22, Math.sign(z) * 0.16, chrome);
    }
    doors.push(d);
  }

  const wheels = [];
  const wheelSpec = [
    ['FL', 1.3, 0.8, bay],
    ['FR', 1.3, -0.8, bay],
    ['RL', -1.35, 0.8, cabin],
    ['RR', -1.35, -0.8, cabin]
  ];
  for (const [id, x, z, host] of wheelSpec) {
    const wx = CAR_X + x;
    const body = makeBody(wx, WHEEL_R, z, params.speed, 0, true);
    body.setAngvel({ x: 0, y: 0, z: -params.speed / WHEEL_R }, true);
    const col = world.createCollider(
      RAPIER.ColliderDesc.cylinder(0.1, WHEEL_R)
        .setRotation(WHEEL_ROT)
        .setMass(m(BASE_MASS.wheel))
        .setFriction(1.15)
        .setRestitution(0.04)
        .setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS)
        .setContactForceEventThreshold(4500),
      body
    );
    tagCollider(col, 'car', body);
    const obj = new THREE.Group();
    buildWheelVisual(obj);
    dynamic.add(obj);
    const rec = { name: 'wheel' + id, body, obj, pos: { x: wx, y: WHEEL_R, z }, host };
    partsByHandle.set(body.handle, rec);
    carBodies.push(body);
    wheelBodies.push(body);
    wheels.push(rec);
  }

  const windows = [];
  function addGlass(parent, x, y, z, hx, hy, hz, mass) {
    const rec = addPart('glass', x, y, z, hx, hy, hz, m(mass), 0.2);
    rec.body.setAngularDamping(0.02);
    mesh(rec.obj, hx * 2, hy * 2, hz * 2, 0, 0, 0, glassMat);
    const arr = [];
    windows.push(arr);
    arr.push(rec);
    arr.parent = parent;
    return rec;
  }
  function glassGrid(parent, rows, cols, x0, x1, y0, y1, zSpan, hx, hy, hz, mass) {
    const group = [];
    for (let i = 0; i < rows; i++) {
      for (let j = 0; j < cols; j++) {
        const u = (i + 0.5) / rows;
        const x = x0 + (x1 - x0) * u;
        const y = y0 + (y1 - y0) * u;
        const z = -zSpan + (j + 0.5) * ((2 * zSpan) / cols);
        const rec = addPart('glass', x, y, z, hx, hy, hz, m(mass), 0.18);
        mesh(rec.obj, Math.max(hx * 2, 0.012), hy * 2 * 0.92, hz * 2 * 0.94, 0, 0, 0, glassMat);
        group.push(rec);
      }
    }
    group.parent = parent;
    windows.push(group);
    return group;
  }

  const wind = glassGrid(cabin, 4, 2, 0.64, 0.36, 1.03, 1.37, 0.62, 0.016, 0.04, 0.28, BASE_MASS.wind);
  const rearG = glassGrid(cabin, 2, 2, -0.98, -1.08, 1.08, 1.30, 0.52, 0.014, 0.048, 0.24, BASE_MASS.rearGlass);
  const sideFL = glassGrid(doors[0], 2, 2, 0.18, 0.62, 0.96, 1.08, 0.0, 0.1, 0.045, 0.012, BASE_MASS.side);
  for (const shard of sideFL) shard.pos.z = doors[0].pos.z;
  sideFL.forEach((shard) => {
    shard.body.setTranslation({ x: shard.pos.x, y: shard.pos.y, z: doors[0].pos.z }, true);
    shard.pos.z = doors[0].pos.z;
  });
  const sideFR = glassGrid(doors[1], 2, 2, 0.18, 0.62, 0.96, 1.08, 0.0, 0.1, 0.045, 0.012, BASE_MASS.side);
  sideFR.forEach((shard) => {
    shard.body.setTranslation({ x: shard.pos.x, y: shard.pos.y, z: doors[1].pos.z }, true);
    shard.pos.z = doors[1].pos.z;
  });
  const sideRL = glassGrid(doors[2], 2, 2, -0.74, -0.22, 0.92, 1.04, 0.0, 0.1, 0.04, 0.012, BASE_MASS.side);
  sideRL.forEach((shard) => {
    shard.body.setTranslation({ x: shard.pos.x, y: shard.pos.y, z: doors[2].pos.z }, true);
    shard.pos.z = doors[2].pos.z;
  });
  const sideRR = glassGrid(doors[3], 2, 2, -0.74, -0.22, 0.92, 1.04, 0.0, 0.1, 0.04, 0.012, BASE_MASS.side);
  sideRR.forEach((shard) => {
    shard.body.setTranslation({ x: shard.pos.x, y: shard.pos.y, z: doors[3].pos.z }, true);
    shard.pos.z = doors[3].pos.z;
  });

  weld(bumperF, nose, 14000, false);
  weld(nose, clip, 26000, false);
  weld(clip, bay, 48000, false);
  weld(bay, cabin, 85000, false);
